import ajv from 'ajv';
import type {ToolDefinition} from '../../types/ai.js';
import type {OutgoingMessage} from '../../types/messages.js';
import {log} from '../../shared/logger.js';

export interface ToolResponse {
  result: string;
  clientMessages?: OutgoingMessage[];
  suppressAssistantResponse?: boolean;
}

export interface ToolContext {
  userId: string | number;
  sessionId?: string;
  workspaceId?: string | number;
  authHeaders?: {
    cookie?: string;
    authorization?: string;
    host?: string;
  };
}

export type ToolExecutor = (input: Record<string, unknown>, context?: ToolContext) => Promise<string | ToolResponse>;

export function normalizeToolResponse(response: string | ToolResponse): ToolResponse {
  return typeof response === 'string' ? {result: response} : response;
}

export type ToolDefinitionSource = ToolDefinition | (() => ToolDefinition);

export interface RegisteredTool {
  definition: ToolDefinition;
  execute: ToolExecutor;
}

interface SchemaValidationError {
  keyword: string;
  instancePath?: string;
  dataPath?: string;
  params: object;
}

interface SchemaValidator {
  (toolInput: unknown): boolean | PromiseLike<unknown>;
  errors?: SchemaValidationError[] | null;
}

interface SchemaCompiler {
  compile(schema: Record<string, unknown>): SchemaValidator;
}

type SchemaCompilerConstructor = new (options: Record<string, unknown>) => SchemaCompiler;

interface StoredTool {
  resolveDefinition: () => ToolDefinition;
  resolveValidator: () => SchemaValidator;
  execute: ToolExecutor;
}

export class ToolRegistry {
  private readonly tools = new Map<string, StoredTool>();

  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
    const registered =
      typeof definition === 'function' ? buildDynamicTool(definition, execute) : buildStaticTool(definition, execute);
    this.tools.set(registered.name, registered.storedTool);
  }

  get(name: string): RegisteredTool | undefined {
    const tool = this.tools.get(name);
    if (!tool) return undefined;
    return {definition: tool.resolveDefinition(), execute: tool.execute};
  }

  getDefinitions(): ToolDefinition[] {
    return [...this.tools.values()].map(t => t.resolveDefinition());
  }

  getPromptInstructions(): string[] {
    return this.getDefinitions()
      .filter(t => t.promptInstructions)
      .map(t => `${t.name}: ${t.promptInstructions}`);
  }

  getExamplePrompts(): string[] {
    return this.getDefinitions().flatMap(t => t.examplePrompts ?? []);
  }

  has(name: string): boolean {
    return this.tools.has(name);
  }

  /** Validates input against inputSchema; see specs/hal-engine-tool-input-validation/spec.md. */
  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
    const tool = this.tools.get(name);
    if (!tool) {
      log.warn('tool', 'tool not found', {name});
      throw new Error(`Unknown tool: ${name}`);
    }
    const validateInput = tool.resolveValidator();
    if (validateInput(input) !== true) {
      const violations = formatValidationErrors(validateInput.errors);
      log.warn('tool', 'input validation failed', {name, violations});
      return {result: `Invalid input for tool "${name}": ${violations.join('; ')}`};
    }
    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
    const rawResult = await tool.execute(input, context);
    const response = normalizeToolResponse(rawResult);
    log.info('tool', 'execution complete', {
      name,
      rawType: typeof rawResult,
      clientMessageCount: response.clientMessages?.length ?? 0,
      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
    });
    return response;
  }
}

function buildDynamicTool(
  definition: () => ToolDefinition,
  execute: ToolExecutor
): {name: string; storedTool: StoredTool} {
  const initial = definition();
  const toolName = initial.name;
  return {
    name: toolName,
    storedTool: {
      resolveDefinition: definition,
      resolveValidator: () => resolveDynamicValidator(toolName, definition().inputSchema),
      execute,
    },
  };
}

function buildStaticTool(definition: ToolDefinition, execute: ToolExecutor): {name: string; storedTool: StoredTool} {
  const validateInput = compileInputSchema(definition.name, definition.inputSchema);
  return {
    name: definition.name,
    storedTool: {
      resolveDefinition: () => definition,
      resolveValidator: () => validateInput,
      execute,
    },
  };
}

const dynamicValidators = new WeakMap<Record<string, unknown>, SchemaValidator>();

function resolveDynamicValidator(toolName: string, inputSchema: Record<string, unknown>): SchemaValidator {
  const cachedValidator = dynamicValidators.get(inputSchema);
  if (cachedValidator) return cachedValidator;
  const compiledValidator = compileInputSchema(toolName, inputSchema);
  dynamicValidators.set(inputSchema, compiledValidator);
  return compiledValidator;
}

function compileInputSchema(toolName: string, inputSchema: Record<string, unknown>): SchemaValidator {
  try {
    return schemaCompiler.compile(inputSchema);
  } catch (cause) {
    const reason = cause instanceof Error ? cause.message : String(cause);
    throw new Error(`Invalid inputSchema for tool "${toolName}": ${reason}`, {cause});
  }
}

const schemaCompiler = createSchemaCompiler(ajv);

function createSchemaCompiler(moduleExport: unknown): SchemaCompiler {
  const CompilerConstructor = resolveCompilerConstructor(moduleExport);
  return new CompilerConstructor({
    strict: false,
    validateFormats: false,
    format: false,
    jsonPointers: true,
    logger: false,
    allErrors: true,
  });
}

function resolveCompilerConstructor(moduleExport: unknown): SchemaCompilerConstructor {
  const unwrapped = isObjectLike(moduleExport) ? moduleExport.default : undefined;
  if (isCompilerConstructor(unwrapped)) return unwrapped;
  if (isCompilerConstructor(moduleExport)) return moduleExport;
  throw new Error('Failed to resolve JSON Schema compiler constructor');
}

function isObjectLike(candidate: unknown): candidate is {default?: unknown} {
  if (candidate === null) return false;
  return typeof candidate === 'object' || typeof candidate === 'function';
}

function isCompilerConstructor(candidate: unknown): candidate is SchemaCompilerConstructor {
  return typeof candidate === 'function';
}

function formatValidationErrors(errors: SchemaValidationError[] | null | undefined): string[] {
  if (!errors || errors.length === 0) return ['input failed schema validation'];
  return errors.map(describeValidationError);
}

function describeValidationError(validationError: SchemaValidationError): string {
  const formatter = KEYWORD_FORMATTERS[validationError.keyword];
  if (formatter) return formatter(validationError);
  const fieldPath = formatErrorPath(validationError);
  if (fieldPath === '<root>') return `input failed "${validationError.keyword}" constraint`;
  return `field "${fieldPath}" failed "${validationError.keyword}" constraint`;
}

const KEYWORD_FORMATTERS: Record<string, (validationError: SchemaValidationError) => string> = {
  required: validationError => {
    const missingProperty =
      'missingProperty' in validationError.params ? String(validationError.params.missingProperty) : '';
    const prefix = formatErrorPath(validationError);
    const requiredPath = prefix === '<root>' ? missingProperty : `${prefix}.${missingProperty}`;
    return `missing required property "${requiredPath}"`;
  },
  type: validationError => {
    const fieldPath = formatErrorPath(validationError);
    const declaredType = 'type' in validationError.params ? validationError.params.type : 'unknown';
    const expectedType = Array.isArray(declaredType) ? declaredType.join(' | ') : String(declaredType);
    return `field "${fieldPath}" must be of type ${expectedType}`;
  },
  enum: validationError => {
    const fieldPath = formatErrorPath(validationError);
    const rawAllowed = 'allowedValues' in validationError.params ? validationError.params.allowedValues : undefined;
    const allowedList = Array.isArray(rawAllowed) ? rawAllowed.map(allowed => JSON.stringify(allowed)) : [];
    return `field "${fieldPath}" must be one of (${allowedList.join(', ')})`;
  },
  additionalProperties: validationError => {
    const unexpectedKey =
      'additionalProperty' in validationError.params ? String(validationError.params.additionalProperty) : '';
    const prefix = formatErrorPath(validationError);
    const unexpectedPath = prefix === '<root>' ? unexpectedKey : `${prefix}.${unexpectedKey}`;
    return `unexpected property "${unexpectedPath}"`;
  },
};

function formatErrorPath(validationError: SchemaValidationError): string {
  const pointer = validationError.instancePath ?? validationError.dataPath ?? '';
  if (!pointer) return '<root>';
  const segments = pointer.slice(1).split('/');
  return segments.map(unescapeJsonPointer).join('.');
}

function unescapeJsonPointer(segment: string): string {
  return segment.replace(/~1/g, '/').replace(/~0/g, '~');
}

