export class ToolRegistry {
  private readonly tools = new Map<string, StoredTool>();

  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
    const registered =
      typeof definition === 'function' ? buildDynamicTool(definition, execute) : buildStaticTool(definition, execute);
    this.tools.set(registered.name, registered.storedTool);
  }

  get(name: string): RegisteredTool | undefined {
    const tool = this.tools.get(name);
    if (!tool) return undefined;
    return {definition: tool.resolveDefinition(), execute: tool.execute};
  }

  getDefinitions(): ToolDefinition[] {
    return [...this.tools.values()].map(t => t.resolveDefinition());
  }

  getPromptInstructions(): string[] {
    return this.getDefinitions()
      .filter(t => t.promptInstructions)
      .map(t => `${t.name}: ${t.promptInstructions}`);
  }

  getExamplePrompts(): string[] {
    return this.getDefinitions().flatMap(t => t.examplePrompts ?? []);
  }

  has(name: string): boolean {
    return this.tools.has(name);
  }

  /** Validates input against inputSchema; see specs/hal-engine-tool-input-validation/spec.md. */
  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
    const tool = this.tools.get(name);
    if (!tool) {
      log.warn('tool', 'tool not found', {name});
      throw new Error(`Unknown tool: ${name}`);
    }
    const validateInput = tool.resolveValidator();
    if (!validateInput(input)) {
      const violations = formatValidationErrors(validateInput.errors);
      log.warn('tool', 'input validation failed', {name, violations});
      return {result: `Invalid input for tool "${name}": ${violations.join('; ')}`};
    }
    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
    const rawResult = await tool.execute(input, context);
    const response = normalizeToolResponse(rawResult);
    log.info('tool', 'execution complete', {
      name,
      rawType: typeof rawResult,
      clientMessageCount: response.clientMessages?.length ?? 0,
      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
    });
    return response;
  }
}

function buildDynamicTool(
  definition: () => ToolDefinition,
  execute: ToolExecutor
): {name: string; storedTool: StoredTool} {
  const initial = definition();
  const toolName = initial.name;
  return {
    name: toolName,
    storedTool: {
      resolveDefinition: definition,
      resolveValidator: () => resolveDynamicValidator(toolName, definition().inputSchema),
      execute,
    },
  };
}

function buildStaticTool(definition: ToolDefinition, execute: ToolExecutor): {name: string; storedTool: StoredTool} {
  const validateInput = compileInputSchema(definition.name, definition.inputSchema);
  return {
    name: definition.name,
    storedTool: {
      resolveDefinition: () => definition,
      resolveValidator: () => validateInput,
      execute,
    },
  };
}

const dynamicValidators = new WeakMap<Record<string, unknown>, ValidateFunction>();

function resolveDynamicValidator(toolName: string, inputSchema: Record<string, unknown>): ValidateFunction {
  const cachedValidator = dynamicValidators.get(inputSchema);
  if (cachedValidator) return cachedValidator;
  const compiledValidator = compileInputSchema(toolName, inputSchema);
  dynamicValidators.set(inputSchema, compiledValidator);
  return compiledValidator;
}

const schemaCompiler = new Ajv({
  strict: false,
  validateFormats: false,
  logger: false,
  allErrors: true,
});

function compileInputSchema(toolName: string, inputSchema: Record<string, unknown>): ValidateFunction {
  try {
    return schemaCompiler.compile(inputSchema);
  } catch (cause) {
    throw new Error(`Invalid inputSchema for tool "${toolName}": ${String(cause)}`, {cause});
  }
}

function formatValidationErrors(errors: ErrorObject[] | null | undefined): string[] {
  return (errors ?? []).map(describeValidationError);
}

function describeValidationError(validationError: ErrorObject): string {
  const formatter = KEYWORD_FORMATTERS[validationError.keyword];
  if (formatter) return formatter(validationError);
  const fieldPath = formatInstancePath(validationError.instancePath);
  if (fieldPath === '<root>') return `input failed "${validationError.keyword}" constraint`;
  return `field "${fieldPath}" failed "${validationError.keyword}" constraint`;
}

const KEYWORD_FORMATTERS: Record<string, (validationError: ErrorObject) => string> = {
  required: validationError => {
    const missingProperty = String(validationError.params.missingProperty);
    const prefix = formatInstancePath(validationError.instancePath);
    const requiredPath = prefix === '<root>' ? missingProperty : `${prefix}.${missingProperty}`;
    return `missing required property "${requiredPath}"`;
  },
  type: validationError => {
    const fieldPath = formatInstancePath(validationError.instancePath);
    const declaredType: unknown = validationError.params.type;
    const expectedType = Array.isArray(declaredType) ? declaredType.join(' | ') : String(declaredType);
    return `field "${fieldPath}" must be of type ${expectedType}`;
  },
  enum: validationError => {
    const fieldPath = formatInstancePath(validationError.instancePath);
    const allowedValues: unknown = validationError.params.allowedValues;
    const allowedList = Array.isArray(allowedValues)
      ? allowedValues.map(allowed => JSON.stringify(allowed))
      : [String(allowedValues)];
    return `field "${fieldPath}" must be one of (${allowedList.join(', ')})`;
  },
  additionalProperties: validationError => {
    const unexpectedKey = String(validationError.params.additionalProperty);
    const prefix = formatInstancePath(validationError.instancePath);
    const unexpectedPath = prefix === '<root>' ? unexpectedKey : `${prefix}.${unexpectedKey}`;
    return `unexpected property "${unexpectedPath}"`;
  },
};

function formatInstancePath(instancePath: string): string {
  if (!instancePath) return '<root>';
  const segments = instancePath.slice(1).split('/');
  return segments.map(unescapeJsonPointer).join('.');
}

function unescapeJsonPointer(segment: string): string {
  return segment.replace(/~1/g, '/').replace(/~0/g, '~');
}

