function createSchemaCompiler(moduleExport: unknown): SchemaCompiler {
  if (isRecordOrFunction(moduleExport) && isCompilerConstructor(moduleExport.default)) {
    return new moduleExport.default({
      strict: false,
      validateFormats: false,
      logger: false,
      allErrors: true,
    });
  }
  throw new Error('Failed to resolve JSON Schema compiler constructor');
}

